css:
  // Local wisteria sidebar: a subtle cream tint above the shared transparency.
  if (THEME.id === "custom-wisteria-alchemy-shop") {
    cssText += '\n@layer dreamskin-community { [data-ds-part="sidebar"] { --ds-user-surface-alpha: 0.50 !important; } }\n';
  }
  // Local wisteria: light transparent chrome and readable summary surface.
  if (THEME.id === "custom-wisteria-alchemy-shop") {
    cssText += `
@layer dreamskin-community {
  html[data-dream-skin="active"] [data-ds-part="header"] {
    background: transparent !important;
    backdrop-filter: none !important;
    color: #30243a !important;
  }
  html[data-dream-skin="active"] :is([data-ds-part="header"], [data-app-shell-titlebar="true"]) :is(button,a,svg,[role="menubar"],[role="menuitem"],[class*="text-token-"]),
  html[data-dream-skin="active"] [id^="application-menu-trigger-"] {
    color: #30243a !important;
    text-shadow: none !important;
  }
  html[data-dream-skin="active"] [data-summary-panel-variant] {
    background: linear-gradient(110deg,rgba(205,190,180,.82) 0%,rgba(239,230,204,.84) 52%,rgba(199,187,177,.82) 100%) !important;
    backdrop-filter: blur(20px) saturate(1.12) brightness(1.05) !important;
    color: #30243a !important;
  }
  html[data-dream-skin="active"] [data-summary-panel-variant] :is(button,a,svg,h3,[class*="text-token-"],[class*="text-tertiary"],[class*="text-secondary"],[class*="text-muted"]) {
    color: #30243a !important;
  }
}
`;
  }
  // Native chrome tint uses the app token as well as the upper bar's own fill.
  if (THEME.id === "custom-wisteria-alchemy-shop") {
    cssText += `
@layer dreamskin-community {
  :root {
    --codex-titlebar-tint: rgba(246,242,239,.72) !important;
  }
  :is([class*="_ApplicationMenuTopBar_"],[data-ds-wisteria-topbar]) {
    --header-tint: rgba(246,242,239,.72) !important;
    --codex-titlebar-tint: rgba(246,242,239,.72) !important;
    background: linear-gradient(110deg,rgba(205,190,180,.82) 0%,rgba(239,230,204,.84) 52%,rgba(199,187,177,.82) 100%) !important;

    backdrop-filter: blur(20px) saturate(1.12) brightness(1.05) !important;
    color: #30243a !important;
  }
  :is([class*="_ApplicationMenuTopBar_"],[data-ds-wisteria-topbar]) :is(button,svg,[role="menubar"],[role="menuitem"]) {
    color: #30243a !important;
    text-shadow: none !important;
  }
}
`;
  }
  // Local wisteria wallpaper tint fades toward the right; slider scales strength.
  if (THEME.id === "custom-wisteria-alchemy-shop") {
    cssText += `
@layer dreamskin-community {
  html[data-dream-skin="active"] {
    --ds-gradient-left: rgba(246,242,239,clamp(0,calc(var(--ds-user-surface-alpha,.26) * 1.8),.85)) !important;
    --ds-gradient-mid: rgba(246,242,239,clamp(0,calc(var(--ds-user-surface-alpha,.26) * .85),1)) !important;
    --ds-gradient-right: rgba(246,242,239,clamp(0,calc(var(--ds-user-surface-alpha,.26) * .15),1)) !important;
    --ds-immersive-edge: var(--ds-gradient-left) !important;
    --ds-immersive-mid: var(--ds-gradient-mid) !important;
    --ds-immersive-far: var(--ds-gradient-right) !important;
    --ds-task-immersive-edge: var(--ds-gradient-left) !important;
    --ds-task-immersive-mid: var(--ds-gradient-mid) !important;
    --ds-task-immersive-far: var(--ds-gradient-right) !important;
    --ds-hero-scrim: linear-gradient(90deg,var(--ds-gradient-left) 0%,var(--ds-gradient-mid) 60%,var(--ds-gradient-right) 100%) !important;
    --ds-task-shade: linear-gradient(90deg,var(--ds-gradient-left) 0%,var(--ds-gradient-mid) 60%,var(--ds-gradient-right) 100%) !important;
    --ds-task-full-veil: linear-gradient(90deg,var(--ds-gradient-left) 0%,var(--ds-gradient-mid) 60%,var(--ds-gradient-right) 100%) !important;
  }
}
`;
  }
  // Local wisteria composer has its own brighter frosted surface.
  if (THEME.id === "custom-wisteria-alchemy-shop") {
    cssText += `
@layer dreamskin-community {
  html[data-dream-skin="active"] [data-ds-part="composer"] {
    --ds-user-surface-alpha: .45 !important;
    --ds-upload-panel-alpha: .45 !important;
    --color-background-composer: transparent !important;
    --color-background-composer-action-bar: transparent !important;
    background: rgba(246,242,239,.45) !important;
    backdrop-filter: blur(24px) saturate(1.10) brightness(1.08) !important;
  }
}
`;
  }
  // Back the queued steering message row above the composer.
  if (THEME.id === "custom-wisteria-alchemy-shop") {
    cssText += `
@layer dreamskin-community {
  html[data-dream-skin="active"] .vertical-scroll-fade-mask[class~="max-h-[30dvh]"] .group[class~="text-size-chat"]:has([role="group"][aria-label]) {
    background: rgba(246,242,239,.72) !important;
    border: 1px solid rgba(255,255,255,.44) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(24px) saturate(1.08) !important;
    -webkit-backdrop-filter: blur(24px) saturate(1.08) !important;
    color: #5c4e7a !important;
  }
  html[data-dream-skin="active"] .vertical-scroll-fade-mask[class~="max-h-[30dvh]"] .group[class~="text-size-chat"]:has([role="group"][aria-label]) :is(.text-secondary,.text-codex-description,button,svg) {
    color: #5c4e7a !important;
  }
}
`;
  }

binding:
// Bind the actual menu row rather than depending on optional shell class names.
const bindWisteriaTopbar = () => {
  if (THEME.id !== "custom-wisteria-alchemy-shop") return;
  const menu = document.querySelector('[role="menubar"]:has([id^="application-menu-trigger-"])');
  if (!menu) return;
  let row = null;
  for (let node = menu; node && node !== document.body; node = node.parentElement) {
    const rect = node.getBoundingClientRect();
    if (rect.height > 0 && rect.top < 8 && rect.bottom <= 72 && rect.width >= window.innerWidth * .90) row = node;
  }
  if (!row) return;
  if (!row.hasAttribute("data-ds-wisteria-topbar")) row.setAttribute("data-ds-wisteria-topbar", "true");
  const paint = "linear-gradient(110deg,rgba(205,190,180,.82) 0%,rgba(239,230,204,.84) 52%,rgba(199,187,177,.82) 100%)";
  if (row.style.getPropertyValue("background") !== paint) row.style.setProperty("background", paint, "important");

};
